      "answer": "<div style='background-color:#f0f8ff; padding:15px; border-left:5px solid #16a085; border-radius:8px;'><p><strong>ઉત્તર:</strong> ૧. તે બીજાનું દુઃખ સમજે છે અને ઉપકાર કરીને અભિમાન કરતો નથી. ૨. તે આખા જગતમાં સૌને વંદન કરે છે અને કોઈની નિંદા કરતો નથી. ૩. તે પરસ્ત્રીને માતા સમાન ગણે છે. ૪. તે ક્યારેય અસત્ય બોલતો નથી અને બીજાના ધનને હાથ અડાડતો નથી.</p><hr><p style='color:#d32f2f; font-weight:bold;'>💡 નિતેશ સરની શોર્ટકટ ટ્રીક: પરદુઃખ, પરધન, પરસ્ત્રી અને પરનિંદા - આ ચાર બાબતોમાં જેનો વ્યવહાર શુદ્ધ તે વૈષ્ણવ.</p></div>"
