      "answer": "<div style='background-color:#f0f8ff; padding:15px; border-left:5px solid #16a085; border-radius:8px;'><p><strong>ઉત્તર:</strong> જે વૈષ્ણવજનનું મન, વાણી અને ચારિત્ર્ય શુદ્ધ હોય, જે કોઈની નિંદા ન કરતો હોય અને જેણે પોતાની ઇન્દ્રિયો પર વિજય મેળવ્યો હોય, એવા શ્રેષ્ઠ પુરુષને જન્મ આપનારી માતા ખરેખર ભાગ્યશાળી છે. આવા ઉત્તમ સંતાનને કારણે તેની માતાનું નામ રોશન થાય છે, તેથી કવિ તેને ધન્ય કહે છે.</p><hr><p style='color:#d32f2f; font-weight:bold;'>💡 નિતેશ સરની શોર્ટકટ ટ્રીક: ઉત્તમ સંતાન = ધન્ય જનની.</p></div>"
